# Break My Fix finding 1, generated by Tracefix: parse_port raises ValueError.
# Property (docstring): Empty or whitespace-only string returns 8080
# Quote: if unset or blank, DEFAULT_PORT (8080) is used
# Run it with pytest: it fails for as long as the code breaks this property.

from svc.config import parse_port


def test_break_my_fix_1() -> None:
    raw = ''
    # The property applies to this input: raw is not None and raw.strip() == ''
    result = parse_port(raw=raw)
    assert result == (8080)
